-- 328: Redesign the SCTP / Customised Training / WPL landing pages to the
--      franchise-style layout (hero + visual timeline + supporting sections),
--      matching /franchising-application.html. Lead forms are unchanged.
--
-- SG-only: gated on the SG marker category 'course-development-service'
-- (partner DBs lack it, so every UPDATE is a no-op there). Content is
-- hex-encoded (UNHEX) and pure ASCII so apply.php's semicolon/backslash
-- splitter and the utf8 PDO connection handle it cleanly. Idempotent:
-- re-runs re-apply the identical content.
--
-- After deploy, flush the Magento cache (Redis) so the new block renders.

SET @sg := (SELECT COUNT(*) FROM catalog_category_entity_varchar cev JOIN eav_attribute ea ON ea.attribute_id=cev.attribute_id AND ea.entity_type_id=3 AND ea.attribute_code='url_key' WHERE cev.store_id=0 AND cev.value='course-development-service');

UPDATE cms_block SET content=UNHEX(''), update_time=NOW() WHERE identifier='sctp_landing' AND @sg>0;

UPDATE cms_block SET content=UNHEX(''), update_time=NOW() WHERE identifier='customised_landing' AND @sg>0;

UPDATE cms_block SET content=UNHEX(''), update_time=NOW() WHERE identifier='wpl_landing' AND @sg>0;

